package org.jlinalg.cli;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import org.jlinalg.distributional.NormalFit;
import static org.jlinalg.cli.Monocle3WorkflowRequest.*;

/** Native analytical normal fitting and declared-tail testing against a supplied background. */
public final class NormalFitToolsCli {
    private NormalFitToolsCli() { }
    static final String SCOPE="Native unweighted analytical normal MLE from complete supplied finite observations. Population variance uses n, not n-1. Optional normal-tail/BH testing preserves every supplied test in order and reports significance without filtering rows. No fitting method, shuffled matrix, background suitability, retention direction, paper version, weights, censoring, optimizer replay or biological calibration is inferred.";
    static final String ACTION="Require exit 0 and result_admitted=true. Read WARNINGS.md, analysis-status.json, provenance.json and every fit/test row. Supply complete finite values with literal unique IDs, declare normal-mle and the intended units; for BACKGROUND declare the background origin, tail, BH, cutoff and strict/inclusive rule. Correct the named input, representability, capacity or heap cause and retry NEW paths. Preserve failed attempts. Do not drop missing values, repair IDs, recode scores or silently rescale to force success.";
    private record Request(String mode,Path samples,Path tests,Path out,String units,String origin,NormalFit.Tail tail,double cutoff,boolean inclusive,long bytes,int observations,int testCount,long operations,long outputBytes) { }
    private record Data(Path original,NextflowFiles.Pin pin,List<String> ids,List<String> tokens,double[] values) { }
    public static void main(String[] args){System.exit(run(args,System.out,System.err));}
    public static int run(String[] args,PrintStream output,PrintStream error){
        if(args.length==0||Arrays.equals(args,new String[]{"--help"})){emit(output,"Normal fitting (native Java)\njava -cp DEVELOPMENT.jar org.jlinalg.cli.NormalFitToolsCli --request request.json\n\nClosed JSON: schema_version=1, mode=FIT|BACKGROUND, estimator=normal-mle, samples, value_units (literal label), out (NEW). Samples TSV: observation_id,value. BACKGROUND additionally requires tests TSV (test_id,value), background_origin=caller-supplied-shuffled-coaccessibility|caller-supplied-reference, tail=upper|lower|two-sided, adjustment=BH, cutoff strictly between0 and1, cutoff_rule=strict|inclusive. FIT refuses test/background fields. Optional maximum_input_bytes=134217728, maximum_observations=1000000, maximum_tests=1000000, maximum_operations=100000000, maximum_output_table_bytes=1073741824. Relative paths resolve against the request. Literal unquoted UTF-8 TSV; no missing-value omission or identifier repair. No external runtime or installation.\n\n"+SCOPE+"\n\n"+ACTION);return 0;}
        try{
            var options=FollowupSupport.options(args,Set.of("request"));Path source=Path.of(FollowupSupport.required(options,"request")).toAbsolutePath().normalize();var sourcePin=NextflowFiles.pin(source,1<<20,()->{});byte[] raw=NextflowFiles.bytes(source,1<<20);require(sourcePin.bytes()==raw.length&&sourcePin.sha256().equals(NextflowFiles.sha(raw)),"Request changed during intake");Request r=parse(object(NextflowParameters.parse(NextflowFiles.utf8(raw),1<<20,100000)),source.getParent());int[] exit={0};
            FollowupSupport.transaction(Map.of("out",r.out.toString()),"native-normal-fit",(stage,manifest)->{
                var warnings=new ArrayList<String>();warnings.add(SCOPE);warnings.add("ESTIMATOR REVIEW: analytical normal-mle solves the unweighted normal likelihood. fitdistrplus's default normal MLE uses a numerical optimizer. Reference agreement does not replay its optimizer, Hessian, covariance, custom starts or all estimation methods. P043 does not name its function, estimator or package version; do not infer them from this selected method.");
                var state=new LinkedHashMap<String,Object>();state.put("result_admitted",false);
                try{
                    Path inputs=Files.createDirectory(stage.resolve("inputs"));Files.write(inputs.resolve("request.json"),raw,StandardOpenOption.CREATE_NEW);verify(source,sourcePin);
                    Data samples=capture(r.samples,inputs.resolve("samples.tsv"),r.bytes,r.observations,"observation_id");Data tests=r.tests==null?null:capture(r.tests,inputs.resolve("tests.tsv"),r.bytes-samples.pin.bytes(),r.testCount,"test_id");var budget=new NormalFit.Budget(r.operations);var fit=NormalFit.fit(samples.values,budget);List<NormalFit.Test> values=tests==null?List.of():NormalFit.tests(fit,tests.values,r.tail,r.cutoff,r.inclusive,budget);
                    Path results=Files.createDirectory(stage.resolve("results"));long generated=0;
                    try(var writer=Files.newOutputStream(results.resolve("fit.tsv"),StandardOpenOption.CREATE_NEW)){
                        generated=write(writer,"estimator\tobservations\tmean\tstandard_deviation\tpopulation_variance\tlog_likelihood\taic\tbic\n",generated,r.outputBytes);
                        generated=write(writer,String.join("\t","normal-mle",Integer.toString(fit.observations()),token(fit.mean()),token(fit.standardDeviation()),token(fit.variance()),token(fit.logLikelihood()),token(fit.aic()),token(fit.bic()))+"\n",generated,r.outputBytes);
                    }
                    long underflow=0,unrepresentableLogTail=0,significant=0;
                    if(tests!=null){
                        warnings.add("BACKGROUND REVIEW REQUIRED: the supplied background's shuffle, independence and suitability are caller declarations. This workflow generates no shuffles and does not validate normality or BH calibration. P043's filtering-out sentence is ambiguous; all rows remain present and meets_declared_cutoff is not an inferred retention instruction.");
                        try(var writer=Files.newOutputStream(results.resolve("tests.tsv"),StandardOpenOption.CREATE_NEW)){
                            generated=write(writer,"test_id\tinput_value\ttail\tp_value\tlog_p_value\tbh_q_value\tlog_bh_q_value\tmeets_declared_cutoff\n",generated,r.outputBytes);
                            for(int i=0;i<values.size();i++){var v=values.get(i);if(v.pValue()==0&&Double.isFinite(v.logPValue()))underflow++;if(v.logPValue()==Double.NEGATIVE_INFINITY)unrepresentableLogTail++;if(v.meetsCutoff())significant++;generated=write(writer,String.join("\t",tests.ids.get(i),tests.tokens.get(i),r.tail.name().toLowerCase(Locale.ROOT).replace('_','-'),token(v.pValue()),token(v.logPValue()),token(v.qValue()),token(v.logQValue()),Boolean.toString(v.meetsCutoff()))+"\n",generated,r.outputBytes);}
                        }
                        if(underflow>0||unrepresentableLogTail>0)warnings.add("TAIL PRECISION WARNING: "+underflow+" linear probabilities underflow to zero with finite log tails; "+unrepresentableLogTail+" log tails are outside representable range. Original numeric zero behavior is retained for ordinary BH and cutoff classification; inspect log_p_value/log_bh_q_value. Numeric zero is not proof of a literally zero probability.");
                    }
                    verify(samples.original,samples.pin);if(tests!=null)verify(tests.original,tests.pin);verify(source,sourcePin);
                    var provenance=new LinkedHashMap<String,Object>();provenance.put("estimator","normal-mle");provenance.put("mode",r.mode);provenance.put("value_units",r.units);provenance.put("observations",samples.values.length);provenance.put("sample_ids",samples.ids);provenance.put("background_origin",r.origin);provenance.put("tail",r.tail==null?null:r.tail.name());provenance.put("adjustment",tests==null?null:"BH");provenance.put("cutoff",tests==null?null:r.cutoff);provenance.put("cutoff_rule",tests==null?null:r.inclusive?"inclusive":"strict");provenance.put("input_sha256",tests==null?Map.of("samples",samples.pin.sha256()):Map.of("samples",samples.pin.sha256(),"tests",tests.pin.sha256()));provenance.put("request_sha256",sourcePin.sha256());provenance.put("operation_count",budget.used());provenance.put("generated_table_bytes",generated);provenance.put("linear_tail_underflows",underflow);provenance.put("unrepresentable_log_tails",unrepresentableLogTail);provenance.put("rows_meeting_declared_cutoff",significant);provenance.put("rows_filtered",false);provenance.put("optimizer_or_paper_replayed",false);NextflowFiles.writeJson(stage.resolve("provenance.json"),provenance);
                    state.put("status","PASS_NATIVE_NORMAL_FIT");state.put("result_admitted",true);state.put("mode",r.mode);state.put("tested_rows",values.size());
                }catch(Exception failure){exit[0]=2;state.put("status","FAIL2_NO_RESULT_ADMITTED");state.put("result_admitted",false);state.put("cause",failure.toString());warnings.add("FAIL2: "+failure);quarantine(stage);}
                catch(OutOfMemoryError failure){exit[0]=2;state.put("status","FAIL2_NO_RESULT_ADMITTED");state.put("result_admitted",false);state.put("cause","Java heap exhausted");warnings.add("FAIL2: Java heap exhausted; choose a permitted heap/input size and retry NEW paths.");quarantine(stage);}
                state.put("required_action",ACTION);NextflowFiles.writeJson(stage.resolve("analysis-status.json"),state);Files.writeString(stage.resolve("WARNINGS.md"),"# "+state.get("status")+"\n\n"+String.join("\n\n",warnings)+"\n\nREQUIRED ACTION: "+ACTION+"\n",StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW);manifest.put("result_admitted",state.get("result_admitted"));manifest.put("scope",SCOPE);
            });emit(exit[0]==0?output:error,(exit[0]==0?"Native normal analysis admitted: ":"FAIL2 NO RESULT ADMITTED: ")+r.out);emit(error,"WARNINGS / REQUIRED ACTIONS: "+r.out.resolve("WARNINGS.md")+"\n"+ACTION);return exit[0];
        }catch(Exception failure){emit(error,"FAIL2 NO RESULT ADMITTED: "+failure+"\n"+ACTION);return 2;}
    }
    private static Request parse(Map<String,Object> m,Path parent)throws IOException{
        Set<String> allowed=Set.of("schema_version","mode","estimator","samples","tests","out","value_units","background_origin","tail","adjustment","cutoff","cutoff_rule","maximum_input_bytes","maximum_observations","maximum_tests","maximum_operations","maximum_output_table_bytes");for(String key:m.keySet())require(allowed.contains(key),"Unknown normal-fit field: "+key);
        integer(m.get("schema_version"),1,1);String mode=text(m.get("mode"));require(Set.of("FIT","BACKGROUND").contains(mode),"Require FIT or BACKGROUND");require(text(m.get("estimator")).equals("normal-mle"),"Choose normal-mle explicitly; other fitdistrplus estimators are not inferred");String units=label(m.get("value_units"));NormalFit.Tail tail=null;double cutoff=0;boolean inclusive=false;String origin=null;
        if(mode.equals("BACKGROUND")){origin=text(m.get("background_origin"));require(Set.of("caller-supplied-shuffled-coaccessibility","caller-supplied-reference").contains(origin),"Declare supplied background origin");tail=switch(text(m.get("tail"))){case "upper"->NormalFit.Tail.UPPER;case "lower"->NormalFit.Tail.LOWER;case "two-sided"->NormalFit.Tail.TWO_SIDED;default->throw new IOException("Declare upper, lower or two-sided tail");};require(text(m.get("adjustment")).equals("BH"),"Declare BH over the complete supplied family");cutoff=finite(m.get("cutoff"),0,1);require(cutoff>0&&cutoff<1,"Require 0<cutoff<1");String rule=text(m.get("cutoff_rule"));require(Set.of("strict","inclusive").contains(rule),"Declare strict or inclusive cutoff rule");inclusive=rule.equals("inclusive");}
        else for(String key:List.of("tests","background_origin","tail","adjustment","cutoff","cutoff_rule"))require(!m.containsKey(key),"FIT refuses background-only field: "+key);
        return new Request(mode,resolve(parent,label(m.get("samples"))),mode.equals("BACKGROUND")?resolve(parent,label(m.get("tests"))):null,resolve(parent,label(m.get("out"))),units,origin,tail,cutoff,inclusive,number(m,"maximum_input_bytes",128L<<20,1,512L<<20),(int)number(m,"maximum_observations",1000000,2,10000000),(int)number(m,"maximum_tests",1000000,1,10000000),number(m,"maximum_operations",100000000,1,10000000000L),number(m,"maximum_output_table_bytes",1L<<30,1,128L<<30));
    }
    private static Data capture(Path original,Path copy,long capacity,int maximum,String first)throws IOException{
        require(capacity>=0,"Complete input byte capacity exceeded");var expected=NextflowFiles.pin(original,capacity,()->{});try(var in=Files.newInputStream(original,LinkOption.NOFOLLOW_LINKS);var out=Files.newOutputStream(copy,StandardOpenOption.CREATE_NEW)){byte[] buffer=new byte[65536];long count=0;for(int n=in.read(buffer);n>=0;n=in.read(buffer)){require(n<=capacity-count,"Input grew beyond byte capacity");out.write(buffer,0,n);count+=n;}require(count==expected.bytes(),"Input size changed during capture");}verify(copy,expected);verify(original,expected);
        String text=NextflowFiles.utf8(Files.readAllBytes(copy));require(!text.startsWith("\ufeff")&&text.indexOf('\0')<0,"Refuse BOM/NUL in literal TSV");String[] lines=text.split("\n",-1);int length=lines.length;if(lines[length-1].isEmpty())length--;require(length>=1,"Empty TSV input");String header=lines[0].endsWith("\r")?lines[0].substring(0,lines[0].length()-1):lines[0];require(header.equals(first+"\tvalue"),"Require exact "+first+", value header");require(length-1<=maximum,"Input exceeds declared row capacity");var ids=new ArrayList<String>();var tokens=new ArrayList<String>();var seen=new HashSet<String>();double[] values=new double[length-1];
        for(int i=1;i<length;i++){String line=lines[i].endsWith("\r")?lines[i].substring(0,lines[i].length()-1):lines[i];require(!line.isEmpty()&&line.indexOf('\r')<0,"Empty/bare-CR row refused");String[] row=line.split("\t",-1);require(row.length==2&&!row[0].isEmpty()&&seen.add(row[0]),"Require unique literal nonempty IDs and exact row width");require(row[1].matches("[+-]?(?:[0-9]+(?:[.][0-9]*)?|[.][0-9]+)(?:[eE][+-]?[0-9]+)?"),"Require complete decimal numeric values; NA/NaN/Inf are not omitted");double value;try{value=Double.parseDouble(row[1]);}catch(NumberFormatException invalid){throw new IOException("Invalid numeric value",invalid);}require(Double.isFinite(value),"Nonfinite observation refused");ids.add(row[0]);tokens.add(row[1]);values[i-1]=value;}
        return new Data(original,expected,List.copyOf(ids),List.copyOf(tokens),values);
    }
    private static long write(OutputStream out,String text,long used,long maximum)throws IOException{byte[] raw=text.getBytes(StandardCharsets.UTF_8);require(raw.length<=maximum-used,"Generated normal tables exceed maximum_output_table_bytes");out.write(raw);return used+raw.length;}
    private static String token(double value){return value==Double.NEGATIVE_INFINITY?"-Inf":Double.toString(value);}
    private static void verify(Path path,NextflowFiles.Pin expected)throws IOException{require(expected.equals(NextflowFiles.pin(path,expected.bytes(),()->{})),"Input/request changed during analysis");}
    private static void quarantine(Path stage)throws IOException{if(Files.exists(stage.resolve("results")))Files.move(stage.resolve("results"),stage.resolve("unadmitted-partial-results"));}
    private static void emit(PrintStream stream,String text){byte[] raw=(text+"\n").getBytes(StandardCharsets.UTF_8);stream.write(raw,0,raw.length);stream.flush();}
}
